<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_Data_Integrity{
 public static function init():void{add_action('admin_menu',[self::class,'menu'],21);}
 public static function menu():void{if(current_user_can('manage_options'))add_submenu_page('edit.php?post_type=nv_application',__('Data Integrity','nvconsult-core'),__('Data Integrity','nvconsult-core'),'manage_options','nvconsult-integrity',[self::class,'render']);}
 public static function render():void{$issues=self::scan();echo'<div class="wrap"><h1>'.esc_html__('NVConsult Data Integrity','nvconsult-core').'</h1><p>'.esc_html__('Read-only checks for broken relationships and inconsistent case data.','nvconsult-core').'</p><table class="widefat striped"><thead><tr><th>'.esc_html__('Object','nvconsult-core').'</th><th>'.esc_html__('Issue','nvconsult-core').'</th></tr></thead><tbody>';if(!$issues)echo'<tr><td colspan="2"><strong>'.esc_html__('No integrity issues detected by current checks.','nvconsult-core').'</strong></td></tr>';foreach($issues as$i)printf('<tr><td>%s</td><td>%s</td></tr>',esc_html($i[0]),esc_html($i[1]));echo'</tbody></table></div>';}
 private static function scan():array{$out=[];$apps=get_posts(['post_type'=>'nv_application','post_status'=>'any','numberposts'=>-1]);foreach($apps as$a){$uid=absint(get_post_meta($a->ID,'_nvconsult_user_id',true));if($uid&&!get_userdata($uid))$out[]=['Application #'.$a->ID,__('Applicant user no longer exists.','nvconsult-core')];$assigned=absint(get_post_meta($a->ID,'_nvconsult_assigned_user_id',true));if($assigned&&!get_userdata($assigned))$out[]=['Application #'.$a->ID,__('Assigned consultant no longer exists.','nvconsult-core')];$type=(string)get_post_meta($a->ID,'_nvconsult_application_type',true);$target=absint(get_post_meta($a->ID,'_nvconsult_target_id',true));if($target){$map=['job'=>'nv_job','program'=>'nv_program','scholarship'=>'nv_scholarship','internship'=>'nv_internship'];if(isset($map[$type])&&get_post_type($target)!==$map[$type])$out[]=['Application #'.$a->ID,__('Opportunity relationship does not match application type.','nvconsult-core')];}}$docs=get_posts(['post_type'=>'nv_document','post_status'=>'any','numberposts'=>-1]);foreach($docs as$d){$aid=absint(get_post_meta($d->ID,'_nvconsult_application_id',true));$att=absint(get_post_meta($d->ID,'_nvconsult_attachment_id',true));if(!$aid||get_post_type($aid)!=='nv_application')$out[]=['Document #'.$d->ID,__('Parent application is missing.','nvconsult-core')];if(!$att||get_post_type($att)!=='attachment')$out[]=['Document #'.$d->ID,__('Attachment is missing.','nvconsult-core')];}return$out;}
}
